1057	bool ZipArchive::resolveEntryCurrentName(const ZipEntry& entry, string& currentName) const {
1058	    struct zip_stat stat;
1059	    zip_stat_init(&stat);
1060	    //a deleted slot is reported with a null name / failing stat even when a newly added
1061	    //entry reuses the name captured by the object: the slot index is the identity
1062	    if (zip_stat_index(zipHandle, entry.getIndex(), ZIP_FL_ENC_GUESS, &stat)!=0) { return false; }
1063	    if (stat.name==nullptr || stat.name[0]=='\0') { return false; }
1064	    currentName = stat.name;
1065	    return true;
