1067	
1068	int ZipArchive::deleteEntry(const ZipEntry& entry) const {
1069	    if (!isOpen()) { return LIBZIPPP_ERROR_NOT_OPEN; }
1070	    if (!isEntryUsable(entry)) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
1071	    if (mode==ReadOnly) { return LIBZIPPP_ERROR_NOT_ALLOWED; } //deletion not allowed
1072	
1073	    /*
1074	     * The entry is identified by its (stable) libzip slot index, not by the name captured
1075	     * in the object: it may have been renamed (possibly several times) through this or
1076	     * another copy of the object, and its old name may even be reused by a newly added
1077	     * entry. Resolve what this slot is called in the CURRENT state. If the slot was
1078	     * deleted, the entry this object represents is gone even if its old name is occupied
1079	     * again: the new entry must not be touched.
1080	     */
1081	    string currentName;
1082	    if (!resolveEntryCurrentName(entry, currentName)) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
1083	
1084	    if (!LIBZIPPP_ENTRY_IS_DIRECTORY(currentName)) {
1085	        int result = zip_delete(zipHandle, entry.getIndex());
1086	        if (result==0) {
1087	            forgetEntryCompressionConfig(entry.getIndex());
1088	            forgetStagedStreamFile(entry.getIndex());
1089	            return 1;
1090	        }
1091	        return LIBZIPPP_ERROR_UNKNOWN; //unable to delete the entry
1092	    } else {
1093	        /*
1094	         * Directory deletion: which entries belong to the directory is evaluated against
1095	         * the CURRENT state and the current name of the directory. Entries added after a
1096	         * move take part, entries moved out or already deleted do not, and entries with a
1097	         * merely similar name (e.g. "ab/" when deleting "a/") are left untouched.
1098	         */
1099	        int counter = 0;
1100	        zip_int64_t nbSlots = zip_get_num_entries(zipHandle, 0);
1101	        for(zip_int64_t i=0 ; i<nbSlots ; ++i) {
1102	            const char* name = zip_get_name(zipHandle, (zip_uint64_t)i, ZIP_FL_ENC_GUESS);
1103	            if (name==nullptr) { continue; } //entry deleted in the current (uncommitted) state
1104	            string entryName(name);
1105	            if (entryName==currentName || isPathDescendant(entryName, currentName)) {
1106	                int result = zip_delete(zipHandle, (zip_uint64_t)i);
1107	                if (result==0) {
1108	                    forgetEntryCompressionConfig((libzippp_uint64)i);
1109	                    forgetStagedStreamFile((libzippp_uint64)i);
1110	                    ++counter;
1111	                }
1112	                else { return LIBZIPPP_ERROR_UNKNOWN; } //unable to remove the current entry
1113	            }
1114	        }
1115	        return counter;
1116	    }
1117	}
