1125	int ZipArchive::renameEntry(const ZipEntry& entry, const string& newNameIn) const {
1126	    if (!isOpen()) { return LIBZIPPP_ERROR_NOT_OPEN; }
1127	    if (!isEntryUsable(entry)) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
1128	    if (mode==ReadOnly) { return LIBZIPPP_ERROR_NOT_ALLOWED; } //renaming not allowed
1129	    if (newNameIn.length()==0) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
1130	
1131	    /*
1132	     * The entry is identified by its (stable) libzip slot index and operated under its
1133	     * CURRENT name: the name captured in the object may be outdated (the entry may have
1134	     * been renamed already, through this object or one of its copies) and the old name
1135	     * may even be reused by a newly added entry. If the slot was deleted, the entry this
1136	     * object represents is gone - the new entry using the same name must never be moved;
1137	     * LIBZIPPP_ERROR_INVALID_ENTRY is returned and every pending modification is kept.
1138	     */
1139	    string sourceName;
1140	    if (!resolveEntryCurrentName(entry, sourceName)) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
1141	
1142	    bool isDir = LIBZIPPP_ENTRY_IS_DIRECTORY(sourceName);
1143	    string newName = newNameIn;
1144	    if (isDir) {
1145	        //a '/' is automatically appended to the destination of a directory
1146	        if (!LIBZIPPP_ENTRY_IS_DIRECTORY(newName)) { newName += LIBZIPPP_ENTRY_PATH_SEPARATOR; }
1147	    } else {
1148	        if (LIBZIPPP_ENTRY_IS_DIRECTORY(newName)) { return LIBZIPPP_ERROR_INVALID_PARAMETER; } //a file cannot be renamed as a directory
1149	    }
1150	
1151	    //renaming to the name the entry currently has is invalid (its name at the time the
1152	    //object was obtained is irrelevant)
1153	    if (newName==sourceName) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
1154	
1155	    /*
1156	     * Enumerate ALL the entries of the CURRENT state of the archive (i.e. including any
1157	     * uncommitted addition/deletion/replacement/rename). Slots freed by zip_delete are
1158	     * reported with a null name by libzip and simply skipped.
1159	     */
1160	    struct RenameItem {
1161	        zip_uint64_t index;
1162	        string oldName;
1163	        string targetName;
1164	    };
1165	    vector<RenameItem> movedItems;
1166	    vector<string> externalNames;
1167	
1168	    zip_int64_t nbSlots = zip_get_num_entries(zipHandle, 0);
1169	    for(zip_int64_t i=0 ; i<nbSlots ; ++i) {
1170	        const char* currentName = zip_get_name(zipHandle, (zip_uint64_t)i, ZIP_FL_ENC_GUESS);
1171	        if (currentName==nullptr) { continue; } //entry deleted in the current (uncommitted) state
1172	
1173	        string name(currentName);
1174	        bool participates = false;
1175	        string targetName;
1176	        if (isDir) {
1177	            //the directory itself is matched by its slot index (authoritative identity);
1178	            //its current descendants are matched by current-name prefix, so entries moved
1179	            //in after the object was obtained take part and entries moved out do not
1180	            if ((zip_uint64_t)i==entry.getIndex()) {
1181	                participates = true;
1182	                targetName = newName;
1183	            } else if (isPathDescendant(name, sourceName)) {
1184	                participates = true; //descendant of the moved directory
1185	                targetName = newName + name.substr(sourceName.length());
1186	            }
1187	        } else {
1188	            //only the slot the object refers to moves, never an entry that merely reuses
1189	            //its old name
1190	            participates = ((zip_uint64_t)i==entry.getIndex());
1191	            targetName = newName;
1192	        }
1193	
1194	        if (participates) {
1195	            movedItems.push_back(RenameItem{(zip_uint64_t)i, name, targetName});
1196	        } else {
1197	            externalNames.push_back(name);
1198	        }
1199	    }
1200	
1201	    //the source slot must still be present in the current archive (resolveEntryCurrentName
1202	    //already ensured this; re-check that the enumeration saw it)
1203	    bool sourceFound = false;
1204	    for(vector<RenameItem>::const_iterator it=movedItems.begin() ; it!=movedItems.end() ; ++it) {
1205	        if (it->index==entry.getIndex()) { sourceFound = true; break; }
1206	    }
1207	    if (!sourceFound) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
1208	
1209	    /*
1210	     * Detect conflicts against the CURRENT state only: any entry that does not participate
1211	     * in the move must not occupy the destination itself nor lie below it. Entries whose
1212	     * parent directories are only implicit (no explicit directory entry in the archive) are
1213	     * listed here as well, so a file such as new/target/last.txt prevents src/ from being
1214	     * moved to new/target/ even when no new/ or new/target/ directory entry exists.
1215	     */
1216	    for(vector<string>::const_iterator it=externalNames.begin() ; it!=externalNames.end() ; ++it) {
1217	        const string& external = *it;
1218	        if (isDir) {
1219	            if (external==newName || external.compare(0, newName.length(), newName)==0) {
1220	                return LIBZIPPP_ERROR_UNKNOWN; //destination already occupied by an external entry: no overwrite, no merge
1221	            }
1222	        } else {
1223	            if (external==newName) {
1224	                return LIBZIPPP_ERROR_UNKNOWN; //the destination file already exists
1225	            }
1226	        }
1227	    }
1228	
1229	    /*
1230	     * Compute the (explicit) parent directories that will be missing once the entries have
1231	     * been moved. A directory that is itself moved never has to be re-created here (it keeps
1232	     * existing as an entry, only its name changes), even when a moved entry's new parent
1233	     * chain goes through it.
1234	     */
1235	    vector<string> parentsToCreate;
1236	    for(vector<RenameItem>::const_iterator it=movedItems.begin() ; it!=movedItems.end() ; ++it) {
1237	        //for a directory target (ending with '/'), the first parent to consider is above the
1238	        //target directory itself, hence the search starts at the penultimate separator
1239	        string::size_type searchPos = it->targetName.length()-1;
1240	        if (LIBZIPPP_ENTRY_IS_DIRECTORY(it->targetName) && searchPos>0) { searchPos -= 1; }
1241	        string::size_type slash = it->targetName.rfind(LIBZIPPP_ENTRY_PATH_SEPARATOR, searchPos);
1242	        while(slash!=string::npos && slash>0) {
1243	            string parent = it->targetName.substr(0, slash+1);
1244	
1245	            //a moved destination already exists as an entry after the move
1246	            bool isMovedDestination = false;
1247	            for(vector<RenameItem>::const_iterator mit=movedItems.begin() ; mit!=movedItems.end() ; ++mit) {
1248	                if (mit->targetName==parent) { isMovedDestination = true; break; }
1249	            }
1250	            if (isMovedDestination) { break; } //all the ancestors above are shared with this moved directory
1251	
1252	            //an external entry already provides the directory (explicitly)
1253	            bool isExternal = false;
1254	            for(vector<string>::const_iterator eit=externalNames.begin() ; eit!=externalNames.end() ; ++eit) {
1255	                if (*eit==parent) { isExternal = true; break; }
1256	            }
1257	            if (isExternal) { break; } //the prefix chain up to this directory already exists
1258	
1259	            bool alreadyScheduled = false;
1260	            for(vector<string>::const_iterator pit=parentsToCreate.begin() ; pit!=parentsToCreate.end() ; ++pit) {
1261	                if (*pit==parent) { alreadyScheduled = true; break; }
1262	            }
1263	            if (!alreadyScheduled) { parentsToCreate.push_back(parent); }
1264	            slash = it->targetName.rfind(LIBZIPPP_ENTRY_PATH_SEPARATOR, slash-1);
1265	        }
1266	    }
1267	    //create the parents from the shallowest to the deepest
1268	    std::sort(parentsToCreate.begin(), parentsToCreate.end());
1269	
1270	    /*
1271	     * Apply the rename deepest-first. This ordering is what makes moving a directory below
1272	     * its own path possible (e.g. a/ to a/b/): the descendants free the names the ancestors
1273	     * are renamed to, and the freshly re-created parent directories are not touched.
1274	     */
1275	    std::sort(movedItems.begin(), movedItems.end(),
1276	              [](const RenameItem& a, const RenameItem& b) { return a.targetName > b.targetName; });
1277	
1278	    vector<zip_uint64_t> renamedIndices;
1279	    vector<string> renamedOldNames;
1280	    bool failure = false;
1281	    for(vector<RenameItem>::const_iterator it=movedItems.begin() ; it!=movedItems.end() ; ++it) {
1282	        int result = zip_file_rename(zipHandle, it->index, it->targetName.c_str(), ZIP_FL_ENC_GUESS);
1283	        if (result!=0) { failure = true; break; }
1284	        renamedIndices.push_back(it->index);
1285	        renamedOldNames.push_back(it->oldName);
1286	    }
1287	
1288	    //create the missing parent directories (e.g. re-create a/ when a/ moved to a/b/)
1289	    vector<zip_uint64_t> createdDirIndices;
1290	    if (!failure) {
1291	        for(vector<string>::const_iterator it=parentsToCreate.begin() ; it!=parentsToCreate.end() ; ++it) {
1292	            zip_int64_t dirIndex = zip_dir_add(zipHandle, it->c_str(), ZIP_FL_ENC_GUESS);
1293	            if (dirIndex<0) { failure = true; break; }
1294	            createdDirIndices.push_back((zip_uint64_t)dirIndex);
1295	        }
1296	    }
1297	
1298	    if (failure) {
1299	        /*
1300	         * The move could not be completed: undo everything done during THIS call so that the
1301	         * archive is restored to its exact pre-call state. The directories created during
1302	         * the move are removed first (they may occupy the original names), then the renames
1303	         * are replayed in the reverse order (shallowest-first). Any other pending change is
1304	         * left untouched.
1305	         */
1306	        for(vector<zip_uint64_t>::reverse_iterator dit=createdDirIndices.rbegin() ; dit!=createdDirIndices.rend() ; ++dit) {
1307	            zip_delete(zipHandle, *dit);
1308	        }
1309	        for(zip_int64_t k=(zip_int64_t)renamedIndices.size()-1 ; k>=0 ; --k) {
1310	            zip_file_rename(zipHandle, renamedIndices[(size_t)k], renamedOldNames[(size_t)k].c_str(), ZIP_FL_ENC_GUESS);
1311	        }
1312	        return LIBZIPPP_ERROR_UNKNOWN;
1313	    }
1314	
1315	    return (int)movedItems.size();
1316	}
