1338	void ZipArchive::forgetStagedStreamFile(libzippp_uint64 index) const {
1339	    map<libzippp_uint64, FILE*>::iterator it = stagedStreamFiles.find(index);
1340	    if (it!=stagedStreamFiles.end()) {
1341	        //the source of the entry is gone (deleted or replaced): libzip never closes
1342	        //the staging file itself, so it is closed exactly once, here
1343	        fclose(it->second);
1344	        stagedStreamFiles.erase(it);
1345	    }
1346	}
