1348	bool ZipArchive::isArchiveCompressionApplicable(void) const {
1349	    if (!useArchiveCompressionMethod && compressionLevel==0) { return true; }
1350	
1351	    //a non-zero default level must be applicable to the default method: libzip does not
1352	    //reject an out-of-range DEFLATE level (it would be written as-is), so the documented
1353	    //range is enforced here, before anything is modified
1354	    libzippp_uint16 effectiveMethod = useArchiveCompressionMethod ? compressionMethod : (libzippp_uint16)ZIP_CM_DEFAULT;
1355	    if (!isCompressionLevelApplicable(effectiveMethod, compressionLevel)) { return false; }
1356	
1357	#ifdef LIBZIPPP_HAS_COMPRESSION_METHOD_SUPPORTED
1358	    if (useArchiveCompressionMethod) {
1359	        return zip_compression_method_supported(compressionMethodToLibzip(compressionMethod), 1)!=0;
1360	    }
1361	#endif
1362	    return true;
1363	}
1364	
1365	bool ZipArchive::isArchiveEncryptionApplicable(void) const {
1366	#ifdef LIBZIPPP_WITH_ENCRYPTION
1367	    if (isEncrypted()) {
1368	  #ifdef LIBZIPPP_HAS_ENCRYPTION_METHOD_SUPPORTED
1369	        return zip_encryption_method_supported((zip_uint16_t)encryptionMethod, 1)!=0;
1370	  #else
1371	        //cannot be checked beforehand: a failure is rolled back after the addition
1372	        return true;
1373	  #endif
1374	    }
1375	#endif
1376	    return true;
1377	}
