1379	bool ZipArchive::createParentDirectories(const string& entryName, vector<libzippp_uint64>& createdDirIndices) const {
1380	    string::size_type lastSlash = entryName.rfind(LIBZIPPP_ENTRY_PATH_SEPARATOR);
1381	    if (lastSlash==string::npos) { return true; } //no parent directory needed
1382	
1383	    string::size_type nextSlash = entryName.find(LIBZIPPP_ENTRY_PATH_SEPARATOR);
1384	    while (nextSlash!=string::npos && nextSlash<=lastSlash) {
1385	        string pathToCreate = entryName.substr(0, nextSlash+1);
1386	        if (!hasEntry(pathToCreate)) {
1387	            libzippp_int64 dirIndex = zip_dir_add(zipHandle, pathToCreate.c_str(), ZIP_FL_ENC_GUESS);
1388	            if (dirIndex<0) {
1389	                //a failed addition must not leave empty parent directories behind
1390	                rollbackCreatedDirectories(createdDirIndices);
1391	                return false;
1392	            }
1393	            createdDirIndices.push_back((libzippp_uint64)dirIndex);
1394	        }
1395	        nextSlash = entryName.find(LIBZIPPP_ENTRY_PATH_SEPARATOR, nextSlash+1);
1396	    }
1397	    return true;
1398	}
1399	
1400	void ZipArchive::rollbackCreatedDirectories(const vector<libzippp_uint64>& createdDirIndices) const {
1401	    //deepest directory first; only the directories created by the failed call are
1402	    //removed, pre-existing ones are never touched
1403	    for(vector<libzippp_uint64>::const_reverse_iterator it=createdDirIndices.rbegin() ; it!=createdDirIndices.rend() ; ++it) {
1404	        zip_delete(zipHandle, *it);
1405	    }
1406	}
1407	
1408	bool ZipArchive::installPreparedSource(const string& entryName, zip_source* source, const vector<libzippp_uint64>& createdDirIndices, libzippp_uint64* addedIndex) const {
1409	    libzippp_int64 result = zip_file_add(zipHandle, entryName.c_str(), source, ZIP_FL_OVERWRITE);
1410	    if (result<0) {
1411	        //the source was not adopted by libzip: release it without touching its data
1412	        zip_source_free(source);
1413	        rollbackCreatedDirectories(createdDirIndices);
1414	        return false;
1415	    }
1416	
1417	    zip_file_set_mtime(zipHandle, result, time(nullptr), 0);
1418	
1419	    bool settingsApplied = true;
1420	    bool compressionStaged = false;
1421	    if (useArchiveCompressionMethod || compressionLevel!=0) {
1422	        //both the default method and the default level selected on the archive apply to
1423	        //the actual write (a zero level keeps the default behaviour of libzip)
1424	        settingsApplied = zip_set_file_compression(zipHandle, result, compressionMethodToLibzip(compressionMethod), compressionLevel)==0;
1425	        compressionStaged = settingsApplied;
1426	    }
1427	#ifdef LIBZIPPP_WITH_ENCRYPTION
1428	    if (settingsApplied && isEncrypted()) {
1429	        settingsApplied = zip_file_set_encryption(zipHandle, result, encryptionMethod, nullptr)==0;
1430	    }
1431	#endif
1432	
1433	    if (!settingsApplied) {
1434	        /*
1435	         * Last-resort rollback: the applicability of the selected compression and
1436	         * encryption methods was checked before anything was changed, so this is only
1437	         * reachable on an unexpected libzip failure. The entry is reverted and the
1438	         * directories created by this call are removed; every other pending change
1439	         * (other entries, deletions, renames, comments) is left untouched. Reverting
1440	         * the entry also frees the source (which never owns the caller's data here).
1441	         */
1442	        zip_unchange(zipHandle, (zip_uint64_t)result);
1443	        rollbackCreatedDirectories(createdDirIndices);
1444	        return false;
1445	    }
1446	
1447	    if (compressionStaged) {
1448	        //the archive defaults were applied to the entry: they are its staged compression
1449	        //configuration for the rest of this opening (see entryCompressionMethods)
1450	        entryCompressionMethods[(libzippp_uint64)result] = compressionMethod;
1451	        entryCompressionLevels[(libzippp_uint64)result] = compressionLevel;
1452	    }
1453	    if (addedIndex!=nullptr) { *addedIndex = (libzippp_uint64)result; }
1454	    return true;
1455	}
1456	
1457	bool ZipArchive::addFile(const string& entryName, const string& file) const {
1458	    if (!isOpen()) { return false; }
1459	    if (mode==ReadOnly) { return false; } //adding not allowed
1460	    if (LIBZIPPP_ENTRY_IS_DIRECTORY(entryName)) { return false; }
1461	
1462	    //the source file must be readable: a missing file must not leave any trace
1463	    //(neither a new entry nor parent directories) in the archive
1464	    FILE* probe = fopen(file.c_str(), "rb");
1465	    if (probe==nullptr) { return false; }
1466	    fclose(probe);
1467	
1468	    //the compression and encryption methods selected on the archive must be applicable
1469	    //by this libzip: this is checked before anything is changed so that a failure
1470	    //neither leaves a new entry behind nor silently falls back to weaker settings
1471	    if (!isArchiveCompressionApplicable()) { return false; }
1472	    if (!isArchiveEncryptionApplicable()) { return false; }
1473	
1474	    vector<libzippp_uint64> createdDirIndices;
1475	    if (!createParentDirectories(entryName, createdDirIndices)) { return false; }
1476	
1477	    zip_source* source = zip_source_file(zipHandle, file.c_str(), 0, -1);
1478	    if (source==nullptr) {
1479	        //unable to create the zip_source
1480	        rollbackCreatedDirectories(createdDirIndices);
1481	        return false;
1482	    }
1483	    libzippp_uint64 index = 0;
1484	    if (!installPreparedSource(entryName, source, createdDirIndices, &index)) { return false; }
1485	    //a stream-staged content previously staged for this entry is not referenced
1486	    //anymore: its staging file is released (see stagedStreamFiles)
1487	    forgetStagedStreamFile(index);
1488	    return true;
1489	}
1490	
1491	bool ZipArchive::addData(const string& entryName, const void* data, libzippp_uint64 length, bool freeData) const {
1492	    if (!isOpen()) { return false; }
1493	    if (mode==ReadOnly) { return false; } //adding not allowed
1494	    if (LIBZIPPP_ENTRY_IS_DIRECTORY(entryName)) { return false; }
1495	
1496	    //a null buffer is only valid for an empty content; anything else is rejected
1497	    //before the archive is touched (the caller keeps the ownership of the data)
1498	    if (data==nullptr && length>0) { return false; }
1499	
1500	    //see addFile: the selected compression/encryption must be applicable beforehand
1501	    if (!isArchiveCompressionApplicable()) { return false; }
1502	    if (!isArchiveEncryptionApplicable()) { return false; }
1503	
1504	    vector<libzippp_uint64> createdDirIndices;
1505	    if (!createParentDirectories(entryName, createdDirIndices)) { return false; }
1506	
1507	    /*
1508	     * The buffer is always handed to libzip with freep=0, even when freeData is true:
1509	     * the ownership is transferred to the archive (see adoptedBuffers) only once the
1510	     * data has been fully accepted. Hence a failed call never frees the caller's
1511	     * memory and a successful one guarantees the buffer is released exactly once,
1512	     * when the pending changes are committed or discarded.
1513	     */
1514	    zip_source* source = zip_source_buffer(zipHandle, data, length, 0);
1515	    if (source==nullptr) {
1516	        //unable to create the zip_source
1517	        rollbackCreatedDirectories(createdDirIndices);
1518	        return false;
1519	    }
1520	    libzippp_uint64 index = 0;
1521	    if (!installPreparedSource(entryName, source, createdDirIndices, &index)) { return false; }
1522	    //a stream-staged content previously staged for this entry is not referenced
1523	    //anymore: its staging file is released (see stagedStreamFiles)
1524	    forgetStagedStreamFile(index);
1525	
1526	    if (freeData && data!=nullptr) {
1527	        adoptedBuffers.push_back(const_cast<void*>(data));
1528	    }
1529	    return true;
1530	}
1531	
1532	bool ZipArchive::addData(const std::string& entryName, const std::basic_string<libzippp_uint8> data) const {
1533	    /*
1534	     * The argument is a copy that is destroyed when this method returns: its content
1535	     * must be copied again into a buffer owned by the archive (through the freeData
1536	     * contract) so that the staged source never references the dead argument when the
1537	     * changes are committed or read back.
1538	     */
1539	    if (data.empty()) { return addData(entryName, nullptr, 0, false); }
1540	    void* copy = malloc(data.size());
1541	    if (copy==nullptr) { return false; }
1542	    memcpy(copy, data.data(), data.size());
1543	    if (!addData(entryName, copy, data.size(), true)) {
1544	        //the ownership was not transferred: the copy is still ours to release
1545	        ::free(copy);
1546	        return false;
1547	    }
1548	    return true;
1549	}
1550	
1551	bool ZipArchive::addData(const string& entryName, std::istream& input, libzippp_uint64 chunksize) const {
1552	    if (!isOpen()) { return false; }
1553	    if (mode==ReadOnly) { return false; } //adding not allowed
1554	    if (entryName.empty()) { return false; }
1555	    if (LIBZIPPP_ENTRY_IS_DIRECTORY(entryName)) { return false; }
1556	
1557	    //see addFile: the selected compression/encryption must be applicable beforehand;
1558	    //all the checks above happen before a single byte is consumed from the stream
1559	    if (!isArchiveCompressionApplicable()) { return false; }
1560	    if (!isArchiveEncryptionApplicable()) { return false; }
1561	
1562	    if (chunksize==0) { chunksize = LIBZIPPP_DEFAULT_CHUNK_SIZE; }
1563	
1564	    /*
1565	     * The content is staged in a temporary file (removed by the operating system as
1566	     * soon as the file is closed) and handed to libzip through a custom source: the
1567	     * memory footprint stays bounded whatever the stream length and, once this method
1568	     * has returned, neither reading the entry nor committing depends on the stream.
1569	     */
1570	    FILE* staging = tmpfile();
1571	    if (staging==nullptr) { return false; }
1572	
1573	    char* chunk = NEW_CHAR_ARRAY(chunksize)
1574	    if (chunk==nullptr) {
1575	        fclose(staging);
1576	        return false;
1577	    }
1578	
1579	    libzippp_uint64 total = 0;
1580	    std::streamsize pending = 0; //bytes extracted by the last read, not staged yet
1581	    bool failed = false;
1582	    bool ended = false;
1583	    try {
1584	        for (;;) {
1585	            input.read(chunk, (std::streamsize)chunksize);
1586	            pending = input.gcount();
1587	            if (pending>0) {
1588	                if (fwrite(chunk, 1, (size_t)pending, staging)!=(size_t)pending) { failed = true; break; } //unable to save the read data
1589	                total += (libzippp_uint64)pending;
1590	                pending = 0;
1591	            }
1592	            if (input.eof()) { ended = true; break; } //normal end, possibly after a final partial chunk
1593	            if (input.fail() || input.bad()) { failed = true; break; } //read error (or an already unusable stream)
1594	        }
1595	    } catch (...) {
1596	        //a stream whose exceptions are enabled throws on its normal end (eofbit/failbit)
1597	        //exactly like on a read error: the stream state tells both cases apart. The
1598	        //bytes extracted before the throw are still reported by gcount() (the pending
1599	        //assignment above did not run), so they are staged too.
1600	        pending = input.gcount();
1601	        if (pending>0) {
1602	            if (fwrite(chunk, 1, (size_t)pending, staging)==(size_t)pending) { total += (libzippp_uint64)pending; }
1603	            else { failed = true; }
1604	        }
1605	        if (!failed) {
1606	            ended = input.eof() && !input.bad();
1607	            failed = !ended;
1608	        }
1609	    }
1610	    delete[] chunk;
1611	
1612	    if (failed || !ended) {
1613	        //the archive has not been touched yet: no entry, no parent directory, and the
1614	        //bytes already consumed from the stream are simply dropped
1615	        fclose(staging);
1616	        return false;
1617	    }
1618	    //a buffered write error may only surface now: the staged content must be complete
1619	    if (fflush(staging)!=0 || ferror(staging)) {
1620	        fclose(staging);
1621	        return false;
1622	    }
1623	
1624	    vector<libzippp_uint64> createdDirIndices;
1625	    if (!createParentDirectories(entryName, createdDirIndices)) {
1626	        fclose(staging);
1627	        return false;
1628	    }
1629	
1630	    IstreamSourceState* state = new (std::nothrow) IstreamSourceState;
1631	    if (state==nullptr) {
1632	        rollbackCreatedDirectories(createdDirIndices);
1633	        fclose(staging);
1634	        return false;
1635	    }
1636	    state->file = staging;
1637	    state->size = total;
1638	    state->offset = 0;
1639	    zip_error_init(&state->error);
1640	
1641	    zip_source* source = zip_source_function(zipHandle, istreamSourceCallback, state);
1642	    if (source==nullptr) {
1643	        delete state;
1644	        rollbackCreatedDirectories(createdDirIndices);
1645	        fclose(staging);
1646	        return false;
1647	    }
1648	
1649	    libzippp_uint64 index = 0;
1650	    if (!installPreparedSource(entryName, source, createdDirIndices, &index)) {
1651	        //the source (and its state) was released by the failed installation; the
1652	        //staging file is still ours
1653	        fclose(staging);
1654	        return false;
1655	    }
1656	
1657	    //a content previously staged from a stream for this very entry is not referenced
1658	    //anymore (its source was released by the overwrite): close its staging file so
1659	    //that successive overwrites of the same entry never leak
1660	    forgetStagedStreamFile(index);
1661	    stagedStreamFiles[index] = staging;
1662	    return true;
1663	}
1664	
1665	bool ZipArchive::addEntry(const string& entryName) const {
1666	    if (!isOpen()) { return false; }
1667	    if (mode==ReadOnly) { return false; } //adding not allowed
1668	    if (!LIBZIPPP_ENTRY_IS_DIRECTORY(entryName)) { return false; }
1669	
1670	    string::size_type nextSlash = entryName.find(LIBZIPPP_ENTRY_PATH_SEPARATOR);
1671	    while (nextSlash!=string::npos) {
1672	        string pathToCreate = entryName.substr(0, nextSlash+1);
1673	        if (!hasEntry(pathToCreate)) {
1674	            libzippp_int64 result = zip_dir_add(zipHandle, pathToCreate.c_str(), ZIP_FL_ENC_GUESS);
1675	            if (result==-1) { return false; }
1676	        }
1677	        nextSlash = entryName.find(LIBZIPPP_ENTRY_PATH_SEPARATOR, nextSlash+1);
1678	    }
1679	
1680	    return true;
1681	}
1682	
1683	void ZipArchive::removeProgressListener(ZipProgressListener* listener) {
1684	    for(vector<ZipProgressListener*>::const_iterator it=listeners.begin() ; it!=listeners.end() ; ++it) {
1685	        ZipProgressListener* l = *it;
1686	        if (l==listener) {
1687	            listeners.erase(it);
1688	            break;
1689	        }
1690	    }
1691	}
1692	
1693	void ZipArchive::setCompressionMethod(CompressionMethod comp)
1694	{
1695	    useArchiveCompressionMethod = comp!=CompressionMethod::DEFAULT;
1696	    compressionMethod = convertCompressionToLibzip(comp);
1697	}
1698	
1699	CompressionMethod ZipArchive::getCompressionMethod(void) const {
1700	    return convertCompressionFromLibzip(compressionMethod);
1701	}
1702	
1703	int ZipArchive::readEntry(const ZipEntry& zipEntry, std::ostream& ofOutput, State state, libzippp_uint64 chunksize) const {
1704	    if (!ofOutput) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
1705	    //a failed stream (failbit/badbit set by write, possibly reported through a
1706	    //std::ios_base::failure when the caller enabled exceptions on the stream) is a
1707	    //write failure: it is reported as LIBZIPPP_ERROR_OWRITE_FAILURE. The stream
1708	    //itself is left untouched (state, exception mask and ownership stay the caller's).
1709	    //Any other exception escaping the write is not a stream error: it is propagated
1710	    //to the caller unchanged (after the reading resources have been released).
1711	    std::function<bool(const void*,libzippp_uint64)> writeFunc = [&ofOutput](const void* data,libzippp_uint64 size){
1712	        try {
1713	            ofOutput.write((char*)data, size);
1714	        } catch (const std::ios_base::failure&) {
1715	            return false;
1716	        }
1717	        return bool(ofOutput);
1718	    };
1719	    return readEntry(zipEntry, writeFunc, state, chunksize);
1720	}
1721	
1722	int ZipArchive::readEntry(const ZipEntry& zipEntry, std::function<bool(const void*,libzippp_uint64)> writeFunc, State state, libzippp_uint64 chunksize) const {
1723	    if (!isOpen()) { return LIBZIPPP_ERROR_NOT_OPEN; }
1724	    //null entries, entries from other archives and entries from a previous opening are
1725	    //rejected before any data delivery (the output stream/callback is left untouched)
1726	    if (!isEntryUsable(zipEntry)) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
1727	
1728	    //resolve the entry in the requested state: its existence and uncompressed size depend
1729	    //on the state. When it does not exist in the state, no data is delivered at all.
1730	    libzippp_uint64 maxSize = 0;
1731	    ZipEntry resolved = resolveEntry(zipEntry, state, &maxSize);
1732	    if (resolved.isNull()) { return LIBZIPPP_ERROR_FOPEN_FAILURE; }
1733	
1734	    if (!chunksize) { chunksize = LIBZIPPP_DEFAULT_CHUNK_SIZE; } // use the default chunk size (512K) if not specified by the user
1735	
1736	    int flag = stateFlags(state);
1737	    struct zip_file* zipFile = zip_fopen_index(zipHandle, resolved.getIndex(), flag);
1738	    if (!zipFile) { return LIBZIPPP_ERROR_FOPEN_FAILURE; }
1739	
1740	    int iRes = LIBZIPPP_OK;
1741	
1742	    //an empty content succeeds without reading anything; a single zero-length delivery is
1743	    //still signalled to the output (this matches the historical behavior)
1744	    if (maxSize==0) {
1745	        bool delivered;
1746	        try {
1747	            delivered = writeFunc("", 0);
1748	        } catch (...) {
1749	            //an exception thrown by the receiver must not leak the opened entry:
1750	            //release it, then let the exception reach the caller unchanged
1751	            zip_fclose(zipFile);
1752	            throw;
1753	        }
1754	        zip_fclose(zipFile);
1755	        return delivered ? LIBZIPPP_OK : LIBZIPPP_ERROR_OWRITE_FAILURE;
1756	    }
1757	
1758	    //only allocate what a single delivery may need (the whole content when it is smaller
1759	    //than the chunk size) instead of the chunk size in every case
1760	    libzippp_uint64 bufferSize = maxSize<chunksize ? maxSize : chunksize;
1761	    char* data = NEW_CHAR_ARRAY(bufferSize)
1762	    if (data!=nullptr) {
1763	        //stream the exact, state-resolved length in successive chunks: this delivers the
1764	        //whole content exactly once (chunksize bigger than, equal to, or not a divisor of
1765	        //the content length are all handled by the same loop)
1766	        try {
1767	            libzippp_uint64 remaining = maxSize;
1768	            while (remaining>0) {
1769	                libzippp_uint64 toRead = remaining<bufferSize ? remaining : bufferSize;
1770	                libzippp_int64 result = zip_fread(zipFile, data, toRead);
1771	                if (result<0) {
1772	                    iRes = LIBZIPPP_ERROR_FREAD_FAILURE;
1773	                    break;
1774	                }
1775	                if (static_cast<libzippp_uint64>(result)!=toRead) {
1776	                    iRes = LIBZIPPP_ERROR_OWRITE_INDEX_FAILURE;
1777	                    break;
1778	                }
1779	                //a receiver reporting false ends the read with a write failure; no
1780	                //further chunk is delivered and the receiver is not invoked again
1781	                if (!writeFunc(data, toRead)) {
1782	                    iRes = LIBZIPPP_ERROR_OWRITE_FAILURE;
1783	                    break;
1784	                }
1785	                remaining -= toRead;
1786	            }
1787	        } catch (...) {
1788	            //whatever the receiver threw: release the chunk buffer and the opened
1789	            //entry, then rethrow the original exception (type and payload preserved)
1790	            delete[] data;
1791	            zip_fclose(zipFile);
1792	            throw;
1793	        }
1794	        delete[] data;
1795	    } else {
1796	        iRes = LIBZIPPP_ERROR_MEMORY_ALLOCATION;
1797	    }
1798	    zip_fclose(zipFile);
1799	    return iRes;
1800	}
