#include <cassert>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>

#include "libzippp.h"

using namespace libzippp;
using namespace std;

//listener that throws when progression reaches >= throwAt
class ThrowingListener : public ZipProgressListener {
public:
    ThrowingListener(double throwAt, bool throwOnCancel=false, const string& msg="boom")
        : throwAt(throwAt), throwOnCancel(throwOnCancel), msg(msg), progCalls(0), cancelCalls(0), lastProg(-1), firstSeen(-1) {}
    double throwAt;
    bool throwOnCancel;
    string msg;
    int progCalls, cancelCalls;
    double lastProg, firstSeen;
    void progression(double p) {
        progCalls++;
        if (firstSeen<0) firstSeen = p;
        lastProg = p;
        if (p >= throwAt) throw runtime_error(msg);
    }
    int cancel() {
        cancelCalls++;
        if (throwOnCancel) throw runtime_error(msg+"-cancel");
        return 0;
    }
};

static string readFile(const string& path) {
    ifstream f(path.c_str(), ios::binary);
    string s((istreambuf_iterator<char>(f)), istreambuf_iterator<char>());
    return s;
}

static void makeBig(const string& path) {
    ZipArchive z(path);
    z.open(ZipArchive::New);
    string big(400000, 'x');
    z.addData("big.txt", big.data(), big.size());
    z.addData("small.txt", "hello", 5);
    assert(z.close()==LIBZIPPP_OK);
}

// 1. exception at initial zero notification
static void t_initialZero() {
    makeBig("t.zip");
    string before = readFile("t.zip");
    {
        ZipArchive z("t.zip");
        z.open(ZipArchive::Write);
        z.addData("new.txt", "NEW", 3);
        ThrowingListener l(0.0); //throws on first notification (p==0): 0>=0
        z.addProgressListener(&l);
        bool threw=false;
        try { z.close(); }
        catch (const runtime_error& e) { threw=true; assert(string(e.what())=="boom"); }
        assert(threw);
        assert(z.isOpen());
        //staged change retained
        assert(z.getEntry("new.txt").readAsText()=="NEW");
        //original retained on disk
        assert(readFile("t.zip")==before);
        //retry after removing listener
        z.removeProgressListener(&l);
        assert(z.close()==LIBZIPPP_OK);
    }
    {
        ZipArchive r("t.zip"); r.open(ZipArchive::ReadOnly);
        assert(r.getEntry("new.txt").readAsText()=="NEW");
        assert(r.getEntry("big.txt").getSize()==400000);
        r.close();
    }
    remove("t.zip");
    cout << "t_initialZero OK\n";
}

// 2. exception during progress (mid commit, big file)
static void t_midProgress() {
    makeBig("t.zip");
    string before = readFile("t.zip");
    {
        ZipArchive z("t.zip");
        z.open(ZipArchive::Write);
        string big2(500000, 'y');
        z.addData("added.bin", big2.data(), big2.size());
        ThrowingListener l(0.5);
        z.setProgressPrecision(0.0);
        z.addProgressListener(&l);
        bool threw=false;
        try { z.close(); }
