    void* external = malloc(16); assert(external); memcpy(external,"EXTERNALDATA!!",14);

    {
        ZipArchive z("t.zip"); assert(z.open(ZipArchive::Write));
        assert(z.addData("ext.txt", external, 14, false)); //caller keeps ownership
        void* adopted = malloc(8); assert(adopted); memcpy(adopted,"ADOPTED!",8);
        assert(z.addData("adopted.txt", adopted, 8, true)); //ownership transferred
        istringstream in("streamed");
        assert(z.addData("stream.txt", in));
        L0 l; z.addProgressListener(&l);
        //destructor: commit aborts (initial 0 throws) -> discard -> adopted + staging released once
    }
    free(external); //must not have been freed by the archive

    //validate original kept and staged changes gone
    { ZipArchive r("t.zip"); r.open(ZipArchive::ReadOnly);
      assert(r.getEntry("orig.txt").readAsText()=="ORIG");
      assert(!r.hasEntry("ext.txt") && !r.hasEntry("adopted.txt") && !r.hasEntry("stream.txt"));
      r.close(); }
    remove("t.zip");
    cout << "destructor-abort resources OK\n";
    return 0;
}
