    libzippp::CommitContext* context = static_cast<libzippp::CommitContext*>(ud);
    context->notifyProgression(progression);
}

static int close_cancel_callback(zip* /*archive*/, void* ud) {
    libzippp::CommitContext* context = static_cast<libzippp::CommitContext*>(ud);
    return context->notifyCancel();
